        return ADCS_E_NULL;
    }

    if (!isfinite(q->w) || !isfinite(q->x) || !isfinite(q->y) || !isfinite(q->z)) {
        return ADCS_E_DEGENERATE;
    }

    n = sqrt(q->w * q->w + q->x * q->x + q->y * q->y + q->z * q->z);

    if (n <= ADCS_EPS_QUAT) {
        return ADCS_E_DEGENERATE;
    }

    factor = 1.0;
    if (fabs(q->w) > ADCS_EPS_QUAT) {
        if (q->w < 0.0) factor = -1.0;
    } else if (fabs(q->x) > ADCS_EPS_QUAT) {
        if (q->x < 0.0) factor = -1.0;
    } else if (fabs(q->y) > ADCS_EPS_QUAT) {
        if (q->y < 0.0) factor = -1.0;
    } else if (fabs(q->z) > ADCS_EPS_QUAT) {
        if (q->z < 0.0) factor = -1.0;
    }

    canonical->w = q->w * factor / n;
    canonical->x = q->x * factor / n;
    canonical->y = q->y * factor / n;
    canonical->z = q->z * factor / n;

    return ADCS_OK;
}

