        return ADCS_E_NOT_FINITE;
    }

    norm_sq = q->w * q->w + q->x * q->x + q->y * q->y + q->z * q->z;
    norm = sqrt(norm_sq);

    if ((!isfinite(norm)) || (norm <= ADCS_EPS_QUAT)) {
        *canonical = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    canonical->w = q->w / norm;
    canonical->x = q->x / norm;
    canonical->y = q->y / norm;
    canonical->z = q->z / norm;

    if (canonical->w < 0.0) {
        canonical->w = -canonical->w;
        canonical->x = -canonical->x;
        canonical->y = -canonical->y;
        canonical->z = -canonical->z;
    } else if (fabs(canonical->w) < FLT64_ZERO) {
        if (canonical->x < 0.0) {
            canonical->w = -canonical->w;
            canonical->x = -canonical->x;
            canonical->y = -canonical->y;
            canonical->z = -canonical->z;
